import{af as d,ad as s,z as l,J as h,K as t,y as a,x as r,ab as i}from"./chunks/framework.D-2fLa7v.js";const v=JSON.parse('{"title":"Four power LEDs","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"devices/capabilities/four-power-leds.md","filePath":"devices/capabilities/four-power-leds.md"}'),p={name:"devices/capabilities/four-power-leds.md"};function c(u,e,b,f,m,y){const n=s("CapabilityDevices"),o=s("LedDemo");return l(),h("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794240761000"},[e[0]||(e[0]=t("h1",{id:"four-power-leds",tabindex:"-1"},[a("Four power LEDs "),t("a",{class:"header-anchor",href:"#four-power-leds","aria-label":'Permalink to "Four power LEDs"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("Four power LEDs show approximate battery level and charging progress. The same indicators can also be used for startup sequences, alerts or model-specific functions. This capability describes the standard "),t("strong",null,"four-bar display"),a(", not every device that happens to have four visible lights.")],-1)),e[2]||(e[2]=t("h2",{id:"devices",tabindex:"-1"},[a("Devices "),t("a",{class:"header-anchor",href:"#devices","aria-label":'Permalink to "Devices"'},"​")],-1)),r(n,{capability:"four-power-leds"}),e[3]||(e[3]=i('<p>The ZE3 revision 01 design also has four orange indicators and the standard firmware uses this display. That design evidence does not establish which firmware is installed on a supplied ZE3; check the revision with support. ZE3 does not have the older Zero ZE2 diagnostic pair.</p><p><a href="/docs/pr/40/devices/rtk/handheld/leds">RH2 RGB status LEDs</a> use a different display and are not covered by these battery-bar thresholds. Custom products, applications and firmware can also differ.</p><h2 id="normal-battery-display" tabindex="-1">Normal battery display <a class="header-anchor" href="#normal-battery-display" aria-label="Permalink to &quot;Normal battery display&quot;">​</a></h2><p>A short status-button press normally shows the battery level briefly. The four indicators use these approximate bands:</p><table tabindex="0"><thead><tr><th>Battery level</th><th>Normal battery display</th></tr></thead><tbody><tr><td>Below 20%</td><td>First indicator flashes when showing status off charge</td></tr><tr><td>20% to below 40%</td><td>1 indicator</td></tr><tr><td>40% to below 60%</td><td>2 indicators</td></tr><tr><td>60% to below 80%</td><td>3 indicators</td></tr><tr><td>80% or more</td><td>4 indicators</td></tr></tbody></table>',5)),r(o,{mode:"battery"}),e[4]||(e[4]=t("p",null,"Four lights are not an exact 100% reading. These examples use orange power LEDs; see your model for its layout and any display overrides.",-1)),e[5]||(e[5]=t("h2",{id:"charging",tabindex:"-1"},[a("Charging "),t("a",{class:"header-anchor",href:"#charging","aria-label":'Permalink to "Charging"'},"​")],-1)),e[6]||(e[6]=t("ul",null,[t("li",null,"Below about 95%, the highest lit battery indicator blinks, roughly one second on and one second off. At very low charge, the first indicator blinks."),t("li",null,"At about 95% or above, the normal charging display becomes steady. This means a high charge level, not an exact 100% reading."),t("li",null,"When unplugged and resting, the lights normally go out after any temporary status display finishes. A button press, startup or other activity can still light them.")],-1)),r(o,{mode:"charging"}),e[7]||(e[7]=i('<p>These are battery-bar patterns, not RH2&#39;s RGB charging colours.</p><h2 id="other-uses-of-the-same-indicators" tabindex="-1">Other uses of the same indicators <a class="header-anchor" href="#other-uses-of-the-same-indicators" aria-label="Permalink to &quot;Other uses of the same indicators&quot;">​</a></h2><p>Startup, alarms, custom applications and remote LED control can temporarily replace the normal display. Some products also use the indicators for a connection or protection state: see the <a href="/docs/pr/40/devices/vehicle/#vehicle-connection-status">VT3 connection display</a> and <a href="/docs/pr/40/devices/pro/#charger-protection">Pro3 charger protection</a>.</p><p>For a practical starting point, use the <a href="/docs/pr/40/guides/leds">LED guide</a>. The number of visible indicators does not by itself establish the number of independently controllable API outputs.</p>',4))])}const w=d(p,[["render",c]]);export{v as __pageData,w as default};
